-- v0.5.0: richer customer records, labels, canned replies, and audit activity.
alter table public.contacts add column if not exists email text, add column if not exists phone text, add column if not exists notes text;
create table public.labels(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null check(length(btrim(name)) between 1 and 40),color text not null default '#1463ff' check(color ~ '^#[0-9a-fA-F]{6}$'),unique(workspace_id,name),unique(id,workspace_id));
create table public.conversation_labels(workspace_id uuid not null references public.workspaces(id) on delete cascade,conversation_id uuid not null references public.conversations(id) on delete cascade,label_id uuid not null,primary key(conversation_id,label_id),foreign key(label_id,workspace_id) references public.labels(id,workspace_id));
create table public.saved_replies(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,title text not null check(length(btrim(title)) between 1 and 80),body text not null check(length(btrim(body)) between 1 and 3000),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.activity_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,conversation_id uuid references public.conversations(id) on delete cascade,actor_id uuid references auth.users(id) on delete set null,event_type text not null check(event_type in ('note_added','status_changed','assigned','label_added','label_removed')),description text not null,created_at timestamptz not null default now());
create index on public.conversation_labels(workspace_id);create index on public.saved_replies(workspace_id);create index on public.activity_events(workspace_id,created_at desc);
create or replace function public.validate_conversation_label() returns trigger language plpgsql set search_path='' as $$begin if not exists(select 1 from public.conversations c where c.id=new.conversation_id and c.workspace_id=new.workspace_id) then raise exception 'Cross-workspace conversation label';end if;return new;end$$;
create trigger conversation_label_scope before insert or update on public.conversation_labels for each row execute function public.validate_conversation_label();
create or replace function public.validate_activity_scope() returns trigger language plpgsql set search_path='' as $$begin if new.conversation_id is not null and not exists(select 1 from public.conversations c where c.id=new.conversation_id and c.workspace_id=new.workspace_id) then raise exception 'Cross-workspace activity';end if;return new;end$$;
create trigger activity_scope before insert or update on public.activity_events for each row execute function public.validate_activity_scope();
alter table public.labels enable row level security;alter table public.conversation_labels enable row level security;alter table public.saved_replies enable row level security;alter table public.activity_events enable row level security;
create policy labels_read on public.labels for select to authenticated using(public.is_workspace_member(workspace_id));
create policy labels_insert on public.labels for insert to authenticated with check(public.workspace_role(workspace_id) in ('owner','agency_admin','agency_agent','client_admin'));
create policy conversation_labels_read on public.conversation_labels for select to authenticated using(public.is_workspace_member(workspace_id));
create policy conversation_labels_insert on public.conversation_labels for insert to authenticated with check(public.workspace_role(workspace_id) in ('owner','agency_admin','agency_agent','client_admin'));
create policy conversation_labels_delete on public.conversation_labels for delete to authenticated using(public.workspace_role(workspace_id) in ('owner','agency_admin','agency_agent','client_admin'));
create policy saved_replies_read on public.saved_replies for select to authenticated using(public.is_workspace_member(workspace_id));
create policy saved_replies_insert on public.saved_replies for insert to authenticated with check(public.workspace_role(workspace_id) in ('owner','agency_admin','agency_agent','client_admin') and created_by=auth.uid());
create policy activity_read on public.activity_events for select to authenticated using(public.is_workspace_member(workspace_id));
-- Audit events are written only by trusted server code, not directly by browser clients.
